package br.com.sistemacardapio.pedido;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import br.com.sistemacardapio.tenant.TenantContext;
@RestController@RequestMapping("/api/pedidos/eventos")@PreAuthorize("hasRole('ADMIN_EMPRESA')")public class PedidoEventoController{private final PedidoEventoService eventos;private final TenantContext tenant;public PedidoEventoController(PedidoEventoService e,TenantContext t){eventos=e;tenant=t;}@GetMapping public SseEmitter conectar(){return eventos.conectar(tenant.empresaIdObrigatoria());}}
